head.b:skin:
:root {
  --background-color: #0f172a;
  --bg-gradient: radial-gradient(circle at top left, #1e293b, #0f172a);
  --text-color: #f1f5f9;
  --text-muted: #94a3b8;
  --primary-color: #38bdf8;
  --primary-glow: rgba(56, 189, 248, 0.4);
  --error-color: #f43f5e;
  --success-color: #10b981;
  --input-background: #1e293b;
  --input-border: #334155;
  --button-hover: #0ea5e9;
  --card-background: rgba(30, 41, 59, 0.7);
  --ad-background: rgba(255, 255, 255, 0.03);
  --ad-text: #475569;
  --nav-bg: rgba(15, 23, 42, 0.8);
}
body.light-mode {
  --background-color: #f8fafc;
  --bg-gradient: radial-gradient(circle at top left, #ffffff, #f1f5f9);
  --text-color: #1e293b;
  --text-muted: #64748b;
  --primary-color: #0284c7;
  --primary-glow: rgba(2, 132, 199, 0.2);
  --error-color: #e11d48;
  --success-color: #059669;
  --input-background: #ffffff;
  --input-border: #e2e8f0;
  --button-hover: #0369a1;
  --card-background: rgba(255, 255, 255, 0.9);
  --ad-background: rgba(0, 0, 0, 0.03);
  --nav-bg: rgba(255, 255, 255, 0.8);
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Inter', sans-serif;
  background: var(--background-color);
  color: var(--text-color);
  line-height: 1.6;
  background-image: var(--bg-gradient);
  background-attachment: fixed;
  transition: all 0.4s ease;
  overflow-x: hidden;
}
body::before {
  content: ""; position: fixed; top: 0; left: 0; width: 100%; height: 100%;
  background: url('https://www.transparenttextures.com/patterns/carbon-fibre.png');
  opacity: 0.03; pointer-events: none; z-index: 1000;
}
header {
  position: sticky; top: 0; width: 100%; background: var(--nav-bg);
  backdrop-filter: blur(12px); z-index: 100; border-bottom: 1px solid var(--input-border);
  padding: 0.75rem 0;
}
nav { max-width: 1200px; margin: 0 auto; display: flex; justify-content: space-between; align-items: center; padding: 0 2rem; }
.logo { font-weight: 800; font-size: 1.25rem; color: var(--primary-color); text-decoration: none; }
.nav-links { display: flex; gap: 1.5rem; list-style: none; align-items: center; }
.nav-links a { text-decoration: none; color: var(--text-color); font-size: 0.9rem; font-weight: 500; transition: color 0.2s; }
.nav-links a:hover, .nav-links a.active { color: var(--primary-color); }
.container { max-width: 1000px; margin: 2rem auto; padding: 0 1.5rem; display: flex; flex-direction: column; align-items: center; gap: 3rem; }
.ad-placeholder { width: 100%; max-width: 728px; height: 90px; background: var(--ad-background); border: 1px dashed var(--ad-text); display: flex; justify-content: center; align-items: center; color: var(--ad-text); font-size: 0.7rem; border-radius: 12px; text-transform: uppercase; letter-spacing: 2px; }
main, .info-section, .partnership-section { text-align: center; background: var(--card-background); padding: 3rem; border-radius: 24px; box-shadow: 0 20px 50px rgba(0, 0, 0, 0.3), 0 0 0 1px var(--input-border); width: 100%; max-width: 800px; backdrop-filter: blur(20px); }
h1 { font-size: 2.5rem; font-weight: 900; margin-bottom: 1rem; letter-spacing: -0.05em; background: linear-gradient(to right, var(--primary-color), #818cf8); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
.lead { color: var(--text-muted); margin-bottom: 2.5rem; font-size: 1.1rem; }
#password-checker-form, #partnership-form { display: flex; flex-direction: column; gap: 1.25rem; text-align: left; }
#password-input, .form-group input, .form-group textarea { padding: 1rem; border: 2px solid var(--input-border); border-radius: 12px; background: var(--input-background); color: var(--text-color); font-size: 1.1rem; outline: none; transition: all 0.3s ease; width: 100%; }
#password-input:focus { border-color: var(--primary-color); box-shadow: 0 0 0 4px var(--primary-glow); }
button[type="submit"], .submit-btn { padding: 1rem; border: none; border-radius: 12px; background: var(--primary-color); color: #fff; font-size: 1.1rem; font-weight: 700; cursor: pointer; transition: all 0.3s ease; }
button[type="submit"]:hover { background: var(--button-hover); transform: translateY(-2px); }
.grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 2rem; text-align: left; margin-top: 2rem; }
.card h3 { color: var(--primary-color); margin-bottom: 0.5rem; }
footer { width: 100%; padding: 4rem 2rem; background: var(--nav-bg); border-top: 1px solid var(--input-border); margin-top: 4rem; text-align: center; }
.footer-content { max-width: 1200px; margin: 0 auto; display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 3rem; text-align: left; }
.copyright { margin-top: 3rem; font-size: 0.8rem; color: var(--ad-text); }
.page-section { display: none; }
.page-section.active { display: block; }

body.script:
//
  function showSection(id) {
    document.querySelectorAll('.page-section').forEach(s => s.classList.remove('active'));
    document.getElementById(id).classList.add('active');
    document.querySelectorAll('.nav-links a').forEach(a => a.classList.remove('active'));
    document.querySelector('a[href="#' + id + '"]')?.classList.add('active');
    window.scrollTo({top: 0, behavior: 'smooth'});
  }
  const form = document.getElementById('password-checker-form');
  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    const pwd = document.getElementById('password-input').value;
    const res = document.getElementById('result-container');
    res.innerHTML = '확인 중...';
    try {
      const hash = Array.from(new Uint8Array(await crypto.subtle.digest('SHA-1', new TextEncoder().encode(pwd))))
        .map(b => b.toString(16).padStart(2, '0')).join('').toUpperCase();
      const prefix = hash.slice(0, 5);
      const suffix = hash.slice(5);
      const response = await fetch('https://api.pwnedpasswords.com/range/' + prefix);
      const data = await response.text();
      const match = data.split('\n').find(line => line.startsWith(suffix));
      if (match) {
        res.innerHTML = `<div style="color:#f43f5e; margin-top:2rem; padding:1.5rem; background:rgba(244,63,94,0.1); border-radius:12px;">위험! ${match.split(':')[1]}번 유출되었습니다.</div>`;
      } else {
        res.innerHTML = `<div style="color:#10b981; margin-top:2rem; padding:1.5rem; background:rgba(16,185,129,0.1); border-radius:12px;">안전합니다!</div>`;
      }
    } catch (err) { res.innerHTML = '오류 발생'; }
  });
  const toggle = document.getElementById('theme-toggle');
  toggle.addEventListener('click', () => {
    document.body.classList.toggle('light-mode');
    localStorage.setItem('theme', document.body.classList.contains('light-mode') ? 'light' : 'dark');
  });
  if(localStorage.getItem('theme') === 'light') document.body.classList.add('light-mode');
  (function() {
    var d = document, s = d.createElement('script');
    s.src = 'https://https-yanghyunmo44-hub-github-io-coding-practive.disqus.com/embed.js';
    s.setAttribute('data-timestamp', +new Date());
    (d.head || d.body).appendChild(s);
  })();
//
